import {generationSettings} from './studio-elements.js';
import {C,$,save,on,modal,esc,toast,methodMarkup,bindMethods,wait} from './studio-ui.js';
import {hub,putHub,initial,uid,importStoryText,makeTopic,selectNovel,logJob,steps} from './workflow-store.js';
const link=(id,text,cls='button')=>`<a class="${cls}" href="./${id}.html" data-nav="${id}">${text}</a>`;
export function go(id){const a=document.createElement('a');a.href=`./${id}.html`;a.dataset.nav=id;document.body.append(a);a.click();a.remove()}
const heading=(title,desc)=>`<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div></div>`;
const options=(items,value)=>items.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('');
let projectFilter='全部项目',projectSort='最近编辑';
const stamp=t=>{const d=new Date(t);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')} ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`};
function projectCover(p){const video=p.workflow.shots.find(sh=>sh.video?.lastFrame?.image)?.video;return {image:p.workflow.coverImage||video?.lastFrame?.image,demo:!p.workflow.coverImage&&video?.kind==='demo'}}
export function projectsPage(){const h=hub(),done=h.projects.filter(p=>p.workflow.exported).length,list=h.projects.filter(p=>projectFilter==='全部项目'||(projectFilter==='只看已完成'?!!p.workflow.exported:!p.workflow.exported)).sort((a,b)=>projectSort==='项目名称'?a.name.localeCompare(b.name):projectSort==='最早编辑'?a.updatedAt-b.updatedAt:b.updatedAt-a.updatedAt);return heading('项目工作台','管理项目，延续灵感。每一次创作都有自己的工作空间。')+`<div class="hub-stats">${[['项目总数',h.projects.length],['创作中',h.projects.length-done],['已完成',done],['失败任务',h.projects.flatMap(p=>p.workflow.jobs||[]).filter(j=>j.status==='失败').length]].map(([t,n])=>`<div><span>${t}</span><strong>${n}</strong></div>`).join('')}</div><div class="project-layout"><section class="panel" id="project-library"><div class="panel-header"><h2>项目记录</h2><div class="project-filters"><select id="project-filter" aria-label="项目状态筛选">${options(['全部项目','只看未完成','只看已完成'],projectFilter)}</select><select id="project-sort" aria-label="项目排序">${options(['最近编辑','最早编辑','项目名称'],projectSort)}</select></div></div><div class="project-grid">${list.map(p=>{const cover=projectCover(p);return `<article class="project-card"><button class="project-cover-button" data-cover-project="${p.id}" aria-label="设置${esc(p.name)}封面">${cover.image?`<img class="project-film-cover" src="${esc(cover.image)}" alt="${esc(p.name)}短片封面">`:'<div class="project-cover-empty">尚无短片封面<br><small>生成后取短片画面，或上传封面</small></div>'}${cover.demo?'<span class="cover-caption">短片示例尾帧</span>':''}</button><div class="panel-header"><h3>${esc(p.name)}</h3><span class="pill ${p.workflow.exported?'success':''}">${p.workflow.exported?'已完成':'创作中'}</span></div><p>${esc(p.type)} · ${esc(p.market)}</p><p class="project-updated">更新于${stamp(p.updatedAt)}</p><a class="button" data-project="${p.id}" href="./creation.html" data-nav="creation">继续创作 →</a></article>`}).join('')||'<div class="empty-state">没有符合筛选条件的项目</div>'}</div></section><section class="panel" id="project-create"><h2>创建项目</h2><p class="helper">先确定作品方向，内容随后展开。</p><label class="field">项目名称<input id="project-name" maxlength="50" placeholder="为这部作品起个名字"></label><label class="field">项目类型<select id="project-type">${options(h.types)}</select></label><details><summary>添加项目类型</summary><div class="inline-fields"><input id="new-type" placeholder="自定义类型"><button class="button" id="add-type">添加</button></div></details><label class="field">目标市场<select id="project-market"><option>中文</option><option>英文</option></select></label><label class="field">视觉风格<select id="project-style">${options(C.s.styles.map(x=>x.name))}</select></label><a href="./settings.html" data-nav="settings">管理风格模板</a><button class="button primary" id="create-project">创建并开始 →</button><p class="helper">画幅与分辨率在分镜生成时设置。</p></section></div>`}
export function bindProjects(){on('add-type',()=>{const n=$('new-type').value.trim();if(!n)return;const h=hub();if(!h.types.includes(n))h.types.push(n);putHub(h);C.render()});$('project-filter').onchange=e=>{projectFilter=e.target.value;C.render()};$('project-sort').onchange=e=>{projectSort=e.target.value;C.render()};document.querySelectorAll('[data-project]').forEach(a=>a.onclick=()=>{const h=hub();h.activeId=a.dataset.project;putHub(h)});document.querySelectorAll('[data-cover-project]').forEach(b=>b.onclick=()=>{const h=hub(),p=h.projects.find(p=>p.id===b.dataset.coverProject);const d=modal('设置短片封面','<label class="field">上传短片画面或封面图片<input type="file" id="project-cover-file" accept="image/png,image/jpeg,image/webp"></label><p class="helper">PNG / JPEG / WebP，不超过2MB。无封面时不使用无关装饰图片。</p>');$('project-cover-file').onchange=e=>{const f=e.target.files[0];if(!f)return;if(f.size>2*1024*1024||!['image/png','image/jpeg','image/webp'].includes(f.type))return toast('请选择不超过2MB的图片');const r=new FileReader();r.onload=()=>{p.workflow.coverImage=r.result;p.updatedAt=Date.now();putHub(h);d.close();C.render()};r.onerror=()=>toast('读取失败，请重新选择');r.readAsDataURL(f)}});on('create-project',()=>{const name=$('project-name').value.trim();if(!name){toast('请输入项目名称');$('project-name').focus();return}const h=hub(),w=initial();w.title=name;w.styles=C.s.styles;w.styleIndex=$('project-style').selectedIndex;w.aspect=null;w.generation={aspect:'',resolution:'1080P',model:'演示视频模型'};w.market=$('project-market').value;h.projects.push({id:w.projectId,name,type:$('project-type').value,market:w.market,updatedAt:Date.now(),workflow:w});h.activeId=w.projectId;putHub(h);go('creation')})}
export function ideaPage(){return heading('创意工作台','从一句话开始，让故事慢慢成形。')+`<section class="panel project-context" id="creation-setup"><strong>${esc(C.s.projectName||C.s.title)}</strong><span>${esc(C.s.market||'中文')}市场</span><span>${esc(C.s.styles[C.s.styleIndex]?.name)}</span>${link('projects','切换项目','text-link')}</section><div class="idea-layout"><section class="panel"><h2>一句话创意</h2><label class="field"><span class="sr-label">一句话创意正文</span><textarea id="idea-content" placeholder="一个人物，一个目标，一次意想不到的转折…">${esc(C.s.idea)}</textarea></label><label class="button story-upload">如果已有小说故事，可点击上传<input id="story-file" type="file" accept=".txt,text/plain"></label><p class="helper" id="story-upload-status" role="status">上传 TXT 后进入故事工作台，保留原文并提炼一个选题卡。</p><div class="generation-action-row"><button class="button primary" id="start-story">AI生成3个故事方案</button>${methodMarkup('writingMethod')}</div></section></div>`}
export function bindIdea(){bindMethods();$('idea-content').oninput=e=>{C.s.idea=e.target.value;save()};$('story-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>1024*1024||!f.name.toLowerCase().endsWith('.txt'))return toast('请选择不超过 1MB 的 TXT 文件');try{$('story-upload-status').textContent='读取原文并提炼选题…';const text=await f.text();if(!text.trim())return toast('文件内容为空');const s=C.s,t=importStoryText(s,f.name,text);logJob(s,'storyExtract',{fileName:f.name,sourceText:text,topic:{id:t.id,title:t.title,logline:t.logline}});save();go('story')}catch{$('story-upload-status').textContent='读取失败，原有内容已保留。'}};on('start-story',async()=>{const text=$('idea-content').value.trim();if(!text)return toast('请先输入一句话创意');$('start-story').disabled=true;await wait(250);if(C.s.mode==='novel'){C.s.topicArchive??=[];C.s.topicArchive.push(...C.s.topics);C.s.topics=[]}C.s.mode='idea';C.s.idea=text;await moreStories();go('story')})}
export async function moreStories(request=''){const s=C.s;const list=[0,1,2].map(i=>({...makeTopic(s,i,request),generatedAt:Date.now(),batchId:uid('batch')}));s.topics=[...list,...s.topics];s.storyPage=0;s.storyFocus=list[0].id;logJob(s,'novel',{topicIds:list.map(x=>x.id),request,stories:list});save();}
export function storyPage(){const s=C.s,start=(s.storyPage||0)*3,visible=s.topics.slice(start,start+3),t=s.topics.find(t=>t.id===s.storyFocus)||visible[0];return heading('故事工作台','比较故事方向，把满意的版本交给剧本。')+(!t?`<section class="panel"><h2>故事从创意开始</h2>${link('creation','输入创意','button primary')}</section>`:`<div class="story-layout"><section id="topic-zone"><div class="panel-header"><h2>候选故事</h2><span class="helper">共 ${s.topics.length} 份</span></div>${visible.map((n,i)=>`<button class="story-choice ${n.id===t.id?'selected':''}" data-story="${n.id}"><span class="story-art cover-${i}"></span><strong>${esc(n.title)}</strong><p>${esc(n.logline)}</p><small>${esc(typeof n.direction==='number'?['重逢','悬念','抉择'][n.direction]:n.direction||'导入故事')} · v${n.version}</small></button>`).join('')}<div class="pager"><button class="button" id="page-up" ${start===0?'disabled':''} aria-label="较新的故事">↑</button><span>${(s.storyPage||0)+1} / ${Math.ceil(s.topics.length/3)}</span><button class="button" id="page-down" ${start+3>=s.topics.length?'disabled':''} aria-label="较早的故事">↓</button></div>${s.mode==='novel'?'<p class="helper">已从TXT提炼1份选题，正文保留原文。</p>':'<button class="button" id="more-stories">再生成 3 个方案</button>'}</section><section class="panel story-editor" id="story-editor"><div class="panel-header"><h2>${esc(t.title)}</h2><span class="pill">v${t.version}</span></div><label class="field">故事正文<textarea id="story-text">${esc(t.text)}</textarea></label><p class="helper">可直接修改；选定时以此处最新文本为准。</p><div class="generation-action-row"><a class="button primary" id="choose-story" href="./script.html" data-nav="script">确定并AI生成剧本</a>${methodMarkup('scriptMethod')}</div></section><aside class="panel" id="story-assistant"><h2>一起打磨这个故事</h2><p class="helper">修改只作用于当前候选。</p><div class="chat-history">${(t.messages||[]).map(m=>`<p>${esc(typeof m==='string'?m:m.text||m.content||'已生成新版本')}</p>`).join('')}</div><label class="field">修改要求<textarea id="story-instruction" placeholder="例如：让结尾更克制，保留人物的犹豫"></textarea></label><button class="button" id="revise-story">生成修改版</button><p class="helper">演示采用规则文本，未连接真实 AI。</p></aside></div>`)}
export function bindStory(){const s=C.s;bindMethods();document.querySelectorAll('[data-story]').forEach(b=>b.onclick=()=>{s.storyFocus=b.dataset.story;save();C.render()});on('page-up',()=>{s.storyPage--;s.storyFocus=s.topics[s.storyPage*3].id;save();C.render()});on('page-down',()=>{s.storyPage=(s.storyPage||0)+1;s.storyFocus=s.topics[s.storyPage*3].id;save();C.render()});on('more-stories',async()=>{await moreStories();C.render()});const t=s.topics.find(t=>t.id===s.storyFocus)||s.topics[(s.storyPage||0)*3];if(!t)return;const update=()=>{if(t.text!==$('story-text').value){t.versions??=[];t.versions.push({text:t.text,version:t.version});t.text=$('story-text').value;t.version++;save()}};$('story-text').onchange=update;on('revise-story',()=>{const instruction=$('story-instruction').value.trim();if(!instruction)return toast('请输入修改要求');update();t.versions??=[];t.versions.push({text:t.text,version:t.version});t.text+='\n\n'+`[修改版演示] ${instruction}。人物停下脚步，重新审视自己的选择，最终以行动回应最初的承诺。`;t.version++;t.messages??=[];t.messages.push({text:instruction},{text:'已生成修改版，请检查全文后选定。'});logJob(s,'novelRevision',{action:'revision',instruction,text:t.text});save();C.render()});$('choose-story').onclick=e=>{update();if(!t.text.trim()){e.preventDefault();return toast('故事不能为空')}const projectName=s.title;selectNovel(s,t);s.title=projectName;save()}}
const kinds=['全部','角色','场景','道具','服饰','站位图','风格模板','声音'];let assetKind='全部',assetSearch='';
export function assetsPage(){const h=hub(),list=h.assets.filter(a=>(assetKind==='全部'||a.kind===assetKind)&&`${a.name} ${a.description}`.includes(assetSearch));return heading('资产库','统一管理角色、场景和创作素材，让好内容可以复用。')+`<div class="asset-toolbar" id="asset-filters">${kinds.map(k=>`<button class="button ${k===assetKind?'primary':''}" data-kind="${k}">${k}</button>`).join('')}</div><div class="panel-header"><input id="asset-search" placeholder="搜索名称或描述" value="${esc(assetSearch)}"><button class="button primary" id="new-asset">新增资产</button></div><div class="asset-grid" id="asset-library">${list.length?list.map(a=>`<article class="panel asset-card">${a.audio?`<audio controls src="${esc(a.audio)}"></audio>`:a.image?`<img src="${esc(a.image)}" alt="${esc(a.name)}">`:`<div class="asset-placeholder">${esc(a.kind)}</div>`}<h3>${esc(a.name)}</h3><p>${esc(a.description)}</p><small>${esc(a.kind)} · v${a.version}</small><div class="section-end"><button class="button" data-edit-asset="${a.id}">查看 / 编辑</button><button class="button" data-use-asset="${a.id}">用于当前项目</button></div></article>`).join(''):'<section class="panel empty-state"><h2>把值得保留的素材放在这里</h2><p>上传参考图、记录角色设定，或建立声音与风格模板。</p></section>'}</div>`}
function assetDialog(id){const h=hub(),a=h.assets.find(a=>a.id===id)||{id:uid('asset'),kind:assetKind==='全部'?'角色':assetKind,name:'',description:'',version:0};const d=modal(a.version?'编辑资产':'新增资产',`<label class="field">名称<input id="asset-name" value="${esc(a.name)}"></label><label class="field">类别<select id="asset-kind">${options(kinds.slice(1),a.kind)}</select></label><label class="field">描述 / 声音或风格指令<textarea id="asset-description">${esc(a.description)}</textarea></label><label class="field">参考图片 / 声音文件（≤ 2MB）<input id="asset-file" type="file" accept="image/png,image/jpeg,image/webp,audio/mpeg,audio/wav,audio/x-wav"></label>${a.image?`<img class="asset-preview" src="${esc(a.image)}" alt="资产预览">`:''}`,'<button class="button primary" id="save-asset">保存资产</button>');let image=a.image,audio=a.audio;$('asset-file').onchange=e=>{const f=e.target.files[0];if(!f)return;if(f.size>2*1024*1024||!['image/png','image/jpeg','image/webp','audio/mpeg','audio/wav','audio/x-wav'].includes(f.type))return toast('请选择不超过 2MB 的图片或音频');const r=new FileReader();r.onload=()=>{if(f.type.startsWith('audio/'))audio=r.result;else image=r.result};r.readAsDataURL(f)};on('save-asset',()=>{const name=$('asset-name').value.trim();if(!name)return toast('请输入资产名称');Object.assign(a,{name,kind:$('asset-kind').value,description:$('asset-description').value,image,audio,version:a.version+1});if(!h.assets.some(x=>x.id===a.id))h.assets.push(a);if(a.kind==='风格模板'){h.config.styles??=C.s.styles;const index=a.systemStyle?a.styleIndex:h.config.styles.length;h.config.styles[index]={name:a.name,text:a.description};a.systemStyle=true;a.styleIndex=index;a.id='style-'+index;C.s.styles=h.config.styles}putHub(h);d.close();C.render()})}
export function bindAssets(){document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{assetKind=b.dataset.kind;C.render()});$('asset-search').onchange=e=>{assetSearch=e.target.value;C.render()};on('new-asset',()=>assetDialog());document.querySelectorAll('[data-edit-asset]').forEach(b=>b.onclick=()=>assetDialog(b.dataset.editAsset));document.querySelectorAll('[data-use-asset]').forEach(b=>b.onclick=()=>{const a=hub().assets.find(x=>x.id===b.dataset.useAsset);if(a.kind==='风格模板'&&a.styleIndex!==undefined){C.s.styleIndex=a.styleIndex;save();toast('已选用风格模板；请检查已有媒体');return}C.s.libraryAssets??=[];if(!C.s.libraryAssets.some(x=>x.id===a.id))C.s.libraryAssets.push(a);save();toast('已加入当前项目素材；分镜参考图中可选择')})}
let taskFilter='全部';
export function tasksPage(){const h=hub(),jobs=h.projects.flatMap(p=>(p.workflow.jobs||[]).map(j=>({...j,project:p.name}))).sort((a,b)=>(b.at||0)-(a.at||0)),list=jobs.filter(j=>taskFilter==='全部'||j.status===taskFilter);return heading('任务记录','追溯每次生成的输入、配置与结果。演示任务不会调用真实模型。')+`<section class="panel" id="task-records"><div class="panel-header"><h2>生成历史 · ${jobs.length}</h2><select id="task-filter" aria-label="任务状态">${options(['全部','成功','失败','运行中'],taskFilter)}</select></div><table class="hub-table"><thead><tr><th>任务</th><th>项目</th><th>时间</th><th>状态</th><th>详情</th></tr></thead><tbody>${list.map(j=>`<tr><td>${esc(steps[j.step]||j.step||'视频生成')}</td><td>${esc(j.project)}</td><td>${j.at?new Date(j.at).toLocaleString():'—'}</td><td><span class="pill">${esc(j.status||'已记录')}</span></td><td><button class="button" data-job="${j.id}">查看快照</button></td></tr>`).join('')}</tbody></table>${!list.length?'<div class="empty-state">暂无任务。开始创作后，生成结果会记录在这里。</div>':''}</section>`}
export function bindTasks(){$('task-filter').onchange=e=>{taskFilter=e.target.value;C.render()};document.querySelectorAll('[data-job]').forEach(b=>b.onclick=()=>{const j=hub().projects.flatMap(p=>p.workflow.jobs||[]).find(j=>j.id===b.dataset.job);modal('任务快照',`<p class="helper">失败任务请返回原环节修正输入后重试，重试保留独立记录。</p><div class="field-pair"><div><h3>${esc(steps[j.step]||j.step)}</h3><p>${esc(j.status||'已记录')} · ${j.at?new Date(j.at).toLocaleString():'历史记录'}</p></div><div><h3>模型与配置</h3><p>${esc(j.input?.model?.name||'演示模型')} · 配置 v${j.input?.configVersion||'—'}</p></div></div><h3>生成结果</h3><p class="task-result">${esc(j.result?.error||j.result?.text||j.result?.script?.text||j.result?.summary||JSON.stringify(j.result||{}).slice(0,450))}</p><details><summary>完整输入与结果 JSON</summary><pre class="json-output">${esc(JSON.stringify(j,null,2))}</pre></details>`)})}
export function settingsPage(){return heading('系统设置','管理模型路由、提示词与风格模板。配置变更只影响后续任务。')+`<div class="settings-grid" id="settings-center">${[['system','大模型配置','文本、图像、视频模型及各环节路由'],['prompts','提示词中心','系统默认与项目覆盖，变量校验与预览'],['audio','音频模型','TTS、配音和配乐环节的模型配置'],['styles','风格模板','新增、编辑风格与模板生成指令'],['generation','视频输出设置','配置尺寸、比例、分辨率和模型默认值']].map(([id,t,d])=>`<button class="panel settings-card" data-setting="${id}"><h2>${t}</h2><p>${d}</p><span>配置 →</span></button>`).join('')}</div><section class="panel"><h2>提示词工程交付</h2><p>R4「AI 交互与提示词定制清单」汇总全部首批接口、输入变量、输出结构与验收要求。</p><p class="helper">凭据仅保存引用名称，不在浏览器保存 API Key；连接测试为模拟。</p></section>`}
export function bindSettingsPage(){document.querySelectorAll('[data-setting]').forEach(b=>b.onclick=()=>b.dataset.setting==='generation'?generationSettings(true):C.settings(b.dataset.setting))}
